function ProductList({ products }: { products: Product[] }) {
  const [query, setQuery] = useState('');

  const visibleProducts = useMemo(
    () =>
      products.filter((p) =>
        p.name.toLowerCase().includes(query.toLowerCase())
      ),
    [products, query]
  );

  return (
    <div>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <ul>
        {visibleProducts.map((p) => (
          <li key={p.id}>{p.name}</li>
        ))}
      </ul>
    </div>
  );
}

function BadList({ items }: { items: Item[] }) {
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [visibleCount, setVisibleCount] = useState(0);

  useEffect(() => {
    setVisibleCount(items.filter((i) => selectedIds.has(i.id)).length);
  }, [items, selectedIds]);

  // If a mutation changes items without triggering setSelectedIds,
  // visibleCount can become stale.
}

function GoodList({ items }: { items: Item[] }) {
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const visibleCount = items.filter((i) => selectedIds.has(i.id)).length;

  return <div>{visibleCount} selected</div>;
}

import { createSelector } from 'reselect';

const selectItems = (state: AppState) => state.items;
const selectCategory = (state: AppState) => state.category;

export const selectFilteredItems = createSelector(
  [selectItems, selectCategory],
  (items, category) =>
    items.filter((item) => item.category === category)
);

function ProductView() {
  const filteredItems = useSelector(selectFilteredItems);
  return <ProductList items={filteredItems} />;
}
